-- Foil is a marker within combined copy totals, not a second inventory tally.
begin;
alter table public.card_inventory add column has_foil boolean not null default false, add column trade_foil boolean not null default false;
alter table public.card_inventory add constraint foil_requires_copy check(not has_foil or quantity>0), add constraint foil_offer_requires_spare check(not trade_foil or (has_foil and quantity>=2));
create function public.album_normalize_foil() returns trigger language plpgsql set search_path=pg_catalog as $$begin if new.quantity=0 then new.has_foil:=false;end if;if new.quantity<2 or not new.has_foil then new.trade_foil:=false;end if;return new;end$$;
revoke all on function public.album_normalize_foil() from public,anon,authenticated;
create trigger inventory_normalize_foil before insert or update on public.card_inventory for each row execute function public.album_normalize_foil();
create function public.album_set_foil(p_season text,p_card smallint,p_has_foil boolean,p_trade_foil boolean,p_expected_actor uuid) returns setof public.card_inventory language plpgsql security definer set search_path=pg_catalog as $$
declare actor uuid:=auth.uid();q integer;
begin
 if actor is null then raise exception 'Log in to edit your album.' using errcode='42501';end if;
 if actor is distinct from p_expected_actor or not exists(select 1 from auth.users where id=actor) then raise exception 'Your account changed. Please retry.' using errcode='42501';end if;
 if p_has_foil is null or p_trade_foil is null then raise exception 'Choose a valid variant.';end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_season||':'||p_card::text,0));
 select quantity into q from public.card_inventory where user_id=actor and season_id=p_season and card_number=p_card for update;
 if q is null or q<1 then raise exception 'Add a copy before marking a foil.';end if;
 if p_trade_foil and (not p_has_foil or q<2) then raise exception 'Keep one total copy before offering a foil.';end if;
 update public.card_inventory set has_foil=p_has_foil,trade_foil=p_trade_foil,updated_at=clock_timestamp() where user_id=actor and season_id=p_season and card_number=p_card;
 return query select * from public.card_inventory where user_id=actor and season_id=p_season and card_number=p_card;
end$$;
revoke all on function public.album_set_foil(text,smallint,boolean,boolean,uuid) from public,anon;
grant execute on function public.album_set_foil(text,smallint,boolean,boolean,uuid) to authenticated;
create function public.card_variant_owned(p_user uuid,p_season text,p_card smallint,p_foil boolean) returns boolean language sql stable set search_path=pg_catalog as $$select exists(select 1 from public.card_inventory where user_id=p_user and season_id=p_season and card_number=p_card and quantity>0 and (not p_foil or has_foil))$$;
create function public.card_variant_offered(p_user uuid,p_season text,p_card smallint,p_foil boolean) returns boolean language sql stable set search_path=pg_catalog as $$select exists(select 1 from public.card_inventory where user_id=p_user and season_id=p_season and card_number=p_card and quantity>=2 and trade_foil=p_foil and (not p_foil or has_foil))$$;
revoke all on function public.card_variant_owned(uuid,text,smallint,boolean),public.card_variant_offered(uuid,text,smallint,boolean) from public,anon,authenticated;
alter table public.exchange_requests add column give_foil boolean not null default false,add column receive_foil boolean not null default false;
drop index public.exchange_pending_unique;
create unique index exchange_pending_unique on public.exchange_requests(sender_id,recipient_id,season_id,give_card,receive_card,initiator_id,give_foil,receive_foil) where status='pending';
create or replace function public.get_player_album(p_uid text,p_album smallint default 4) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
select jsonb_build_object('uid',p.game_id,'name',p.display_name,'avatar',p.avatar_url,'season',s.id,'inventory',(select coalesce(jsonb_agg(jsonb_build_object('card_number',i.card_number,'quantity',i.quantity,'has_foil',i.has_foil,'trade_foil',i.trade_foil) order by i.card_number),'[]'::jsonb) from public.card_inventory i where i.user_id=p.user_id and i.season_id=s.id)) from public.profiles p cross join public.album_seasons s where p.game_id<>'' and p.game_id=p_uid and (p.album_public or p.trade_enabled) and s.game_album_id=p_album
$$;
create or replace function public.exchange_search_variants(p_season text,p_star integer default null,p_type text default null,p_mode text default null,p_initiator text default null,p_online boolean default false,p_attempts boolean default false,p_limit integer default 20,p_offset integer default 0,p_receive integer default null,p_give integer default null,p_receive_foil boolean default false,p_give_foil boolean default false) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
with listings as (
 select p.user_id,p.game_id,p.display_name,p.avatar_url,ep.last_seen,coalesce(pref.rarity_mode,'Same Rarity') rarity_mode,coalesce(pref.trades_left_today,3) trades_left_today,
 (select max(i.updated_at) from public.card_inventory i where i.user_id=p.user_id and i.season_id=p_season and i.quantity>=2 and i.trade_foil=p_receive_foil and public.trade_card_available(p_season,i.card_number)) freshness,
 (select jsonb_agg(i.card_number order by i.card_number) from public.card_inventory i join public.album_cards c using(season_id,card_number) where i.user_id=p.user_id and i.season_id=p_season and i.quantity>=2 and i.trade_foil=p_receive_foil and public.trade_card_available(p_season,i.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star)) ft,
 (select coalesce(jsonb_agg(jsonb_build_object('give',a.card_number,'receive',b.card_number,'give_foil',p_give_foil,'receive_foil',p_receive_foil) order by a.card_number,b.card_number),'[]'::jsonb) from public.card_inventory yours join public.album_cards a on a.season_id=yours.season_id and a.card_number=yours.card_number cross join public.card_inventory theirs join public.album_cards b on b.season_id=theirs.season_id and b.card_number=theirs.card_number where yours.user_id=auth.uid() and exists(select 1 from public.profiles own where own.user_id=auth.uid() and own.game_id<>'') and yours.season_id=p_season and yours.quantity>=2 and yours.trade_foil=p_give_foil and theirs.user_id=p.user_id and theirs.season_id=p_season and theirs.quantity>=2 and theirs.trade_foil=p_receive_foil and public.trade_card_available(p_season,a.card_number) and public.trade_card_available(p_season,b.card_number) and (p_type is null or b.gold=(p_type='gold')) and (p_star is null or b.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=a.card_number and k.quantity>0 and (not p_give_foil or k.has_foil)) and not exists(select 1 from public.card_inventory k where k.user_id=auth.uid() and k.season_id=p_season and k.card_number=b.card_number and k.quantity>0 and (not p_receive_foil or k.has_foil)) and public.trade_accepts(auth.uid(),p_season,a.stars,b.stars) and public.trade_accepts(p.user_id,p_season,b.stars,a.stars)) swaps
,
 (select coalesce(jsonb_agg(yours.card_number order by yours.card_number),'[]'::jsonb) from public.card_inventory yours join public.album_cards c on c.season_id=yours.season_id and c.card_number=yours.card_number where yours.user_id=auth.uid() and yours.season_id=p_season and yours.quantity>=2 and yours.trade_foil=p_give_foil and exists(select 1 from public.profiles own where own.user_id=auth.uid() and own.game_id<>'' and own.trade_enabled) and coalesce((select rarity_mode from public.album_trade_preferences where user_id=auth.uid() and season_id=p_season),'Same Rarity')<>'No Trading' and public.trade_card_available(p_season,yours.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=yours.card_number and k.quantity>0 and (not yours.trade_foil or k.has_foil))) gifts
,
 (select coalesce(jsonb_agg(theirs.card_number order by theirs.card_number),'[]'::jsonb) from public.card_inventory theirs join public.album_cards c on c.season_id=theirs.season_id and c.card_number=theirs.card_number where theirs.user_id=p.user_id and theirs.season_id=p_season and theirs.quantity>=2 and theirs.trade_foil=p_receive_foil and auth.uid() is not null and public.trade_card_available(p_season,theirs.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=auth.uid() and k.season_id=p_season and k.card_number=theirs.card_number and k.quantity>0 and (not p_receive_foil or k.has_foil)) and not exists(select 1 from public.card_inventory yours where yours.user_id=auth.uid() and yours.season_id=p_season and yours.quantity>=2 and public.trade_card_available(p_season,yours.card_number) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=yours.card_number and k.quantity>0 and (not yours.trade_foil or k.has_foil)))) gift_requests
 from public.profiles p left join public.exchange_presence ep on ep.user_id=p.user_id left join public.album_trade_preferences pref on pref.user_id=p.user_id and pref.season_id=p_season where p.trade_enabled and p.game_id<>'' and coalesce((select preferences.rarity_mode from public.album_trade_preferences preferences where preferences.user_id=p.user_id and preferences.season_id=p_season),'Same Rarity')<>'No Trading' and p.user_id is distinct from auth.uid() and not public.exchange_blocked(auth.uid(),p.user_id) and (not p_online or ep.last_seen>now()-interval '90 seconds') and (not p_attempts or coalesce(pref.trades_left_today,3)>0) and (p_mode is null or coalesce(pref.rarity_mode,'Same Rarity')=p_mode) and (p_initiator is null or (p_initiator='them' and coalesce(pref.trades_left_today,3)>0) or (p_initiator='me' and auth.uid() is not null and coalesce((select mine.trades_left_today from public.album_trade_preferences mine where mine.user_id=auth.uid() and mine.season_id=p_season),3)>0))
),page as (select * from listings where (ft is not null or jsonb_array_length(gifts)>0 or p_give is not null)
 and (p_receive is null or ft @> jsonb_build_array(p_receive))
 and (p_give is null or (exists(select 1 from public.album_cards c where c.season_id=p_season and c.card_number=p_give and public.trade_card_available(p_season,c.card_number) and (p_receive is not null or ((p_star is null or c.stars=p_star) and (p_type is null or c.gold=(p_type='gold'))))) and not exists(select 1 from public.card_inventory owned where owned.user_id=listings.user_id and owned.season_id=p_season and owned.card_number=p_give and owned.quantity>0 and (not p_give_foil or owned.has_foil))))
 order by freshness desc,user_id limit least(50,greatest(1,p_limit)) offset greatest(0,p_offset))
select coalesce(jsonb_agg(jsonb_build_object('id',user_id,'uid',game_id,'name',display_name,'avatar',avatar_url,'updated_at',freshness,'online',coalesce(last_seen>now()-interval '90 seconds',false),'last_seen',last_seen,'rarity_mode',rarity_mode,'trades_left_today',trades_left_today,'ft',ft,'swaps',swaps,'gifts',gifts,'gift_requests',gift_requests,'give_foil',p_give_foil,'receive_foil',p_receive_foil) order by freshness desc,user_id),'[]'::jsonb) from page
$$;

revoke all on function public.exchange_search_variants(text,integer,text,text,text,boolean,boolean,integer,integer,integer,integer,boolean,boolean) from public;
grant execute on function public.exchange_search_variants(text,integer,text,text,text,boolean,boolean,integer,integer,integer,integer,boolean,boolean) to anon,authenticated;
create or replace function public.exchange_search_listings(p_season text,p_star integer default null,p_type text default null,p_mode text default null,p_initiator text default null,p_online boolean default false,p_attempts boolean default false,p_limit integer default 20,p_offset integer default 0,p_receive integer default null,p_give integer default null) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
select public.exchange_search_variants(p_season,p_star,p_type,p_mode,p_initiator,p_online,p_attempts,p_limit,p_offset,p_receive,p_give,false,false) $$;
create or replace function public.exchange_action(p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
#variable_conflict use_column
declare actor uuid:=auth.uid();peer uuid;rid uuid;req public.exchange_requests;msg text;season text:=coalesce(p_payload->>'season','autumn-tales');give_no smallint;receive_no smallint;initiator uuid;result jsonb;since timestamptz;seen timestamptz;give_stars smallint;receive_stars smallint;eligible boolean;give_foil boolean:=coalesce((p_payload->>'give_foil')::boolean,false);receive_foil boolean:=coalesce((p_payload->>'receive_foil')::boolean,false);
begin
 if actor is null then raise exception 'Log in to use Card Exchange.' using errcode='42501';end if;
 if jsonb_typeof(p_payload)<>'object' then raise exception 'Invalid request.';end if;
 if not exists(select 1 from auth.users where id=actor) then raise exception 'This account no longer exists.' using errcode='42501';end if;
 if p_payload ? 'expected_actor' and p_payload->>'expected_actor' is distinct from actor::text then raise exception 'Your account changed. Please retry.' using errcode='42501';end if;
 if p_action in('send','gift','request','request_gift') and not exists(select 1 from public.album_seasons where id=season) then raise exception 'Unsupported album season.';end if;
 -- A per-account transaction lock serializes sends, blocks and rate checks.
 perform pg_advisory_xact_lock(hashtextextended(actor::text,0));
 if p_action='heartbeat' then
  insert into public.exchange_presence(user_id,last_seen) values(actor,clock_timestamp()) on conflict(user_id) do update set last_seen=excluded.last_seen;return '{}'::jsonb;
 elsif p_action='offline' then
  update public.exchange_presence set last_seen=least(last_seen,now()-interval '91 seconds') where user_id=actor;return '{}'::jsonb;
 elsif p_action='requests' then
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'direction',case when r.sender_id=actor then 'sent' else 'received' end,'person',jsonb_build_object('id',p.user_id,'name',p.display_name,'online',coalesce(ep.last_seen>now()-interval '90 seconds',false),'last_seen',ep.last_seen),'give',case when r.sender_id=actor then r.give_card else r.receive_card end,'receive',case when r.sender_id=actor then r.receive_card else r.give_card end,'give_foil',case when r.sender_id=actor then r.give_foil else r.receive_foil end,'receive_foil',case when r.sender_id=actor then r.receive_foil else r.give_foil end,'initiator_id',r.initiator_id,'at',extract(epoch from r.created_at)*1000) order by r.created_at desc),'[]'::jsonb) into result from public.exchange_requests r join public.profiles p on p.user_id=case when r.sender_id=actor then r.recipient_id else r.sender_id end left join public.exchange_presence ep on ep.user_id=p.user_id where actor in(r.sender_id,r.recipient_id) and r.status='pending' and r.expires_at>now() and not public.exchange_blocked(actor,p.user_id);return result;
 elsif p_action='recall' then
  rid:=(p_payload->>'id')::uuid;update public.exchange_requests set status='recalled' where id=rid and sender_id=actor and status='pending';if not found then raise exception 'Request is unavailable.';end if;return '{}'::jsonb;
 elsif p_action='inbox' then
  with peers as(select recipient_id peer from public.exchange_messages where sender_id=actor and created_at>now()-interval '7 days' union select sender_id from public.exchange_messages where recipient_id=actor and created_at>now()-interval '7 days' union select peer_id from public.exchange_blocks where owner_id=actor),items as(
   select p.user_id,p.display_name,ep.last_seen,coalesce(st.read_at,'-infinity') read_at,coalesce(st.deleted_at,'-infinity') deleted_at,exists(select 1 from public.exchange_blocks b where b.owner_id=actor and b.peer_id=p.user_id) blocked from peers join public.profiles p on p.user_id=peers.peer left join public.exchange_presence ep on ep.user_id=p.user_id left join public.exchange_chat_state st on st.owner_id=actor and st.peer_id=p.user_id)
  select coalesce(jsonb_agg(jsonb_build_object('id',i.user_id,'name',i.display_name,'online',coalesce(i.last_seen>now()-interval '90 seconds',false),'lastSeen',i.last_seen,'blocked',i.blocked,'read',case when i.read_at='-infinity' then 0 else extract(epoch from i.read_at)*1000 end,'unread',not i.blocked and exists(select 1 from public.exchange_messages m where m.sender_id=i.user_id and m.recipient_id=actor and m.created_at>greatest(i.read_at,i.deleted_at,now()-interval '7 days')),'messages',coalesce((select jsonb_agg(jsonb_build_object('text',m.body,'at',extract(epoch from m.created_at)*1000,'mine',m.sender_id=actor) order by m.created_at) from (select * from public.exchange_messages m where ((m.sender_id=actor and m.recipient_id=i.user_id) or (m.recipient_id=actor and m.sender_id=i.user_id)) and m.created_at>greatest(i.deleted_at,now()-interval '7 days') order by m.created_at desc limit 1)m),'[]'::jsonb))) ,'[]'::jsonb) into result from items i where i.blocked or exists(select 1 from public.exchange_messages m where actor in(m.sender_id,m.recipient_id) and i.user_id in(m.sender_id,m.recipient_id) and m.created_at>greatest(i.deleted_at,now()-interval '7 days'));return result;
 end if;
 peer:=(p_payload->>'peer')::uuid;if peer is null or peer=actor or not exists(select 1 from public.profiles where user_id=peer) then raise exception 'Player is unavailable.';end if;
 -- Pair lock prevents concurrent block/send/request races in either direction.
 perform pg_advisory_xact_lock(hashtextextended(least(actor,peer)::text||greatest(actor,peer)::text,1));
 if p_action='block' then
  insert into public.exchange_blocks values(actor,peer) on conflict do nothing;update public.exchange_requests set status='recalled' where status='pending' and actor in(sender_id,recipient_id) and peer in(sender_id,recipient_id);return '{}'::jsonb;
 elsif p_action='unblock' then delete from public.exchange_blocks where owner_id=actor and peer_id=peer;return '{}'::jsonb;
 elsif p_action='delete' then
  insert into public.exchange_chat_state(owner_id,peer_id,deleted_at,read_at) values(actor,peer,clock_timestamp(),clock_timestamp()) on conflict(owner_id,peer_id) do update set deleted_at=excluded.deleted_at,read_at=excluded.read_at;return '{}'::jsonb;
 elsif p_action='thread' then
  select coalesce(deleted_at,'-infinity') into since from public.exchange_chat_state where owner_id=actor and peer_id=peer;since:=coalesce(since,'-infinity');seen:=clock_timestamp();
  select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'text',m.body,'at',extract(epoch from m.created_at)*1000,'mine',m.sender_id=actor,'read',m.created_at<=coalesce(other.read_at,'-infinity')) order by m.created_at),'[]'::jsonb) into result from (select * from public.exchange_messages where ((sender_id=actor and recipient_id=peer) or(sender_id=peer and recipient_id=actor)) and created_at>greatest(since,now()-interval '7 days') order by created_at desc limit 200)m left join public.exchange_chat_state other on other.owner_id=peer and other.peer_id=actor;
  select max(created_at) into seen from public.exchange_messages where sender_id=peer and recipient_id=actor and created_at>greatest(since,now()-interval '7 days');
  if seen is not null then insert into public.exchange_chat_state(owner_id,peer_id,read_at) values(actor,peer,seen) on conflict(owner_id,peer_id) do update set read_at=excluded.read_at where exchange_chat_state.read_at<excluded.read_at;end if;
  return jsonb_build_object('messages',result,'blocked',public.exchange_blocked(actor,peer),'blocked_by_me',exists(select 1 from public.exchange_blocks where owner_id=actor and peer_id=peer));
 end if;
 if p_action not in('send','gift','request','request_gift') then raise exception 'Unknown exchange action.';end if;
 if public.exchange_blocked(actor,peer) then raise exception 'Messaging with this player is unavailable.';end if;
 if not exists(select 1 from public.profiles where user_id=actor and game_id<>'') then raise exception 'Set your game UID in Account first.';end if;
 eligible:=exists(select 1 from public.profiles p where p.user_id=peer and p.trade_enabled and p.game_id<>'' and coalesce((select rarity_mode from public.album_trade_preferences where user_id=peer and season_id=season),'Same Rarity')<>'No Trading');
 if not eligible and not (p_action='send' and exists(select 1 from public.exchange_messages where sender_id=peer and recipient_id=actor and created_at>now()-interval '7 days')) then raise exception 'This player is not accepting new exchanges.';end if;
 if p_action in('gift','request') then
  give_no:=(p_payload->>'give')::smallint;receive_no:=(p_payload->>'receive')::smallint;
  if not exists(select 1 from public.profiles where user_id=actor and trade_enabled) or coalesce((select rarity_mode from public.album_trade_preferences where user_id=actor and season_id=season),'Same Rarity')='No Trading' then raise exception 'Enable trading visibility in Account first.';end if;
  if not exists(select 1 from public.card_inventory where user_id=actor and season_id=season and card_number=give_no and quantity>=2 and trade_foil=give_foil) or exists(select 1 from public.card_inventory where user_id=peer and season_id=season and card_number=give_no and quantity>0 and (not give_foil or has_foil)) or not public.trade_card_available(season,give_no) then raise exception 'This offered card is no longer available.';end if;
 end if;
 if p_action='request_gift' then
  receive_no:=(p_payload->>'receive')::smallint;
  if not exists(select 1 from public.profiles where user_id=actor and game_id<>'' and trade_enabled) or coalesce((select rarity_mode from public.album_trade_preferences where user_id=actor and season_id=season),'Same Rarity')='No Trading' then raise exception 'Enable trading visibility in Account first.';end if;
  if not public.trade_card_available(season,receive_no) or not exists(select 1 from public.card_inventory where user_id=peer and season_id=season and card_number=receive_no and quantity>=2 and trade_foil=receive_foil) or exists(select 1 from public.card_inventory where user_id=actor and season_id=season and card_number=receive_no and quantity>0 and (not receive_foil or has_foil)) then raise exception 'This requested gift is no longer available.';end if;
  if exists(select 1 from public.card_inventory yours where yours.user_id=actor and yours.season_id=season and yours.quantity>=2 and public.trade_card_available(season,yours.card_number) and not exists(select 1 from public.card_inventory k where k.user_id=peer and k.season_id=season and k.card_number=yours.card_number and k.quantity>0 and (not yours.trade_foil or k.has_foil))) then raise exception 'You have a spare they need. Open the matching cards to arrange a trade.';end if;
 end if;
 if p_action='request' then
  if not exists(select 1 from public.card_inventory where user_id=peer and season_id=season and card_number=receive_no and quantity>=2 and trade_foil=receive_foil) or exists(select 1 from public.card_inventory where user_id=actor and season_id=season and card_number=receive_no and quantity>0 and (not receive_foil or has_foil)) or not public.trade_card_available(season,receive_no) then raise exception 'This requested card is no longer available.';end if;
  select stars into give_stars from public.album_cards where season_id=season and card_number=give_no;select stars into receive_stars from public.album_cards where season_id=season and card_number=receive_no;
  if not public.trade_accepts(actor,season,give_stars,receive_stars) or not public.trade_accepts(peer,season,receive_stars,give_stars) then raise exception 'Trade settings no longer allow this exchange.';end if;
  initiator:=case p_payload->>'initiator' when 'them' then peer when 'me' then actor else null end;if initiator is null then raise exception 'Choose who initiates the exchange.';end if;
  if coalesce((select trades_left_today from public.album_trade_preferences where user_id=initiator and season_id=season),3)<1 then raise exception 'The initiator has no attempts remaining.';end if;
  update public.exchange_requests set status='recalled' where sender_id=actor and recipient_id=peer and status='pending' and expires_at<=now();
  if (select count(*) from public.exchange_requests where sender_id=actor and created_at>now()-interval '1 minute')>=20 then raise exception 'Please wait before sending more requests.';end if;
  insert into public.exchange_requests(sender_id,recipient_id,season_id,give_card,receive_card,initiator_id,give_foil,receive_foil) values(actor,peer,season,give_no,receive_no,initiator,give_foil,receive_foil) on conflict(sender_id,recipient_id,season_id,give_card,receive_card,initiator_id,give_foil,receive_foil) where status='pending' do update set status='pending' returning id into rid;
  msg:='Offering No. '||give_no||case when give_foil then ' Foil' else ' Normal' end||' for your No. '||receive_no||case when receive_foil then ' Foil.' else ' Normal.' end;
  if not exists(select 1 from public.exchange_messages where sender_id=actor and recipient_id=peer and body=msg and created_at>now()-interval '1 minute') then insert into public.exchange_messages(sender_id,recipient_id,body) values(actor,peer,msg);end if;return jsonb_build_object('id',rid);
 end if;
 msg:=case when p_action='gift' then 'I can gift No. '||give_no||case when give_foil then ' Foil.' else ' Normal.' end when p_action='request_gift' then 'Could you gift me No. '||receive_no||case when receive_foil then ' Foil?' else ' Normal?' end else btrim(p_payload->>'text') end;
 if msg is null or char_length(msg) not between 1 and 1000 then raise exception 'Messages must contain 1–1000 characters.';end if;
 if (select count(*) from public.exchange_messages where sender_id=actor and created_at>now()-interval '1 minute')>=20 then raise exception 'Please wait before sending more messages.';end if;
 insert into public.exchange_messages(sender_id,recipient_id,body) values(actor,peer,msg) returning id into rid;return jsonb_build_object('id',rid);
end $$;
revoke all on function public.exchange_action(text,jsonb) from public,anon;
grant execute on function public.exchange_action(text,jsonb) to authenticated;

create or replace function public.exchange_listings(p_season text,p_star integer default null,p_type text default null,p_mode text default null,p_initiator text default null,p_online boolean default false,p_attempts boolean default false,p_limit integer default 20,p_offset integer default 0) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
select public.exchange_search_variants(p_season,p_star,p_type,p_mode,p_initiator,p_online,p_attempts,p_limit,p_offset,null,null,false,false) $$;
notify pgrst,'reload schema';
commit;
